import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    static int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static int union(int[] parent, int[] size, int a, int b) {
        int rootA = find(parent, a);
        int rootB = find(parent, b);
        if (rootA == rootB) return 0;

        if (size[rootA] < size[rootB]) {
            int temp = rootA;
            rootA = rootB;
            rootB = temp;
        }
        parent[rootB] = rootA;
        size[rootA] += size[rootB];
        return 1;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        int[] heights = new int[n];
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            heights[i] = fs.nextInt();
            order[i] = i;
        }

        Arrays.sort(order, (a, b) -> Integer.compare(heights[b], heights[a]));

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] size = new int[n];

        int components = 0;
        int maxComponents = 0;

        for (int start = 0; start < n; ) {
            int end = start + 1;
            int height = heights[order[start]];
            while (end < n && heights[order[end]] == height) end++;

            for (int k = start; k < end; k++) {
                int i = order[k];
                parent[i] = i;
                size[i] = 1;
                components++;
            }

            for (int k = start; k < end; k++) {
                int i = order[k];
                if (i > 0 && parent[i - 1] != -1) {
                    components -= union(parent, size, i, i - 1);
                }
                if (i + 1 < n && parent[i + 1] != -1) {
                    components -= union(parent, size, i, i + 1);
                }
            }

            maxComponents = Math.max(maxComponents, components);
            start = end;
        }

        System.out.println(maxComponents + 1);
    }
}
